import pc from 'punycode.js'

function f(url, arr, log) {
  if (!url || arr.indexOf(url) > 0) {
    log('skip, arr=' + arr)
    return 'keep ' + url
  }
  log('using arr=' + arr)
  return 'recoded ' + pc.encode(url)
}

console.log(f('http:', ['http:', 'https:', 'mailto:'], console.log))
